def solution(s):
    lines = s.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(n):
        s_i, r_i = map(int, lines[i+1].split())
        points.append((1.0/s_i, 1.0/r_i, i+1))

    # Sort by x, then by y
    points.sort()

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Build lower convex hull
    lower_hull = []
    for p in points:
        while len(lower_hull) >= 2 and cross_product(lower_hull[-2], lower_hull[-1], p) <= 0:
            lower_hull.pop()
        lower_hull.append(p)

    # Extract and sort index
    winners = [p[2] for p in lower_hull]
    winners.sort()
    return ' '.join(map(str, winners)) + ' \n'
