    adj = [[] for _ in range(n + 1)]
    for edge_id in range(m):
        idx = edge_id + 1
        u = edges[edge_id]['u']
        v = edges[edge_id]['v']
        adj[u].append((v, edge_id))
        adj[v].append((u, edge_id))

    def is_connected(skip_edge_ids):
        """Check if s and t are still connected"""
        visited = [False] * (n + 1)
        queue = deque([s])
        visited[s] = True
        while queue:
            curr = queue.popleft()
            if curr == t:
                return True
            for neighbor, edge_id in adj[curr]:
                if edge_id not in skip_edge_ids and not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return False

    def get_edge_cost(edge_id):
        return edges[edge_id - 1]['w']

    # Check case 0: no edges removed
    if not is_connected(set()):
        return "0\n0\n"

    # Check case 1: remove 1 edge
    min_cost = float('inf')
    best_single = None
    for i in range(m):
