                min_cost = cost
                best_single = [i + 1]

    if best_single is not None:
        return f"{min_cost}\n1\n{' '.join(map(str, best_single))}"

    # Check case 2: remove 2 edges
    min_cost = float('inf')
    best_pair = None
    for i in range(m):
        edge_id_i = i
        for j in range(i + 1, m):
            edge_id_j = j
            total_cost = edges[i]['w'] + edges[j]['w']
            if total_cost >= min_cost:
                continue
            edge_set = {edge_id_i, edge_id_j}
            if not is_connected(edge_set):
