def solution(input_data):
    lines = input_data.strip().split('\n')

    n, m = map(int, lines[0].split())
    adj = defaultdict(list)

    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    x = list(map(int, lines[m + 1].split()))

    # Find all vertices with odd visit requirements
    odd_vertices = [i for i in range(1, n + 1) if x[i - 1] == 1]

    # If count is odd, impossible (paths need even number of odd endpoints)
    if len(odd_vertices) % 2 != 0:
        return "-1\n"

    # If no odd vertices, empty path is valid
    if len(odd_vertices) == 0:
        return "0\n"

    # Build a path by pairing consecutive odd vertices and finding paths between them
    result = []

    for i in range(0, len(odd_vertices), 2):
        u = odd_vertices[i]
        v = odd_vertices[i + 1]

        # BFS to find path between u and v
        if u == v:
            result.append(u)
            continue

        queue = [(u, [u])]
        visited = {u}
        found = False

        while queue and not found:
            node, path = queue.pop(0)
            for neighbor in adj[node]:
                if neighbor == v:
                    result.extend(path[1:])  # Skip starting node to avoid double counting
                    result.append(u)
                    result.append(v)
                    found = True
                    break
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))

    # Count visits and verify constraints
    count = [0] * (n + 1)
    for v in result:
        count[v] += 1

    # Output the result
