        parts = lines[idx].strip().split()
        idx += 1
        n, m = int(parts[0]), int(parts[1])

        matrix = []
        for i in range(n):
            while idx < len(lines) and not lines[idx].strip():
                idx += 1
            matrix.append(lines[idx])
            idx += 1

        count = count_squares(matrix, n, m)
        result_lines.append(str(count))

    return '\n'.join(result_lines)

def count_squares(matrix, n, m):
    seen = set()
    count = 0

    # Axis-aligned squares: check each possible top-left corner and size
    for r1 in range(n):
        for c1 in range(m):
            for s in range(2, min(n - r1, m - c1) + 1):
                r2 = r1 + s - 1
                c2 = c1 + s - 1
                key = (r1, c1, s)

                valid = check_axis_square(matrix, r1, c1, r2, c2, n, m)
                if valid:
                    seen.add(key)
                    count += 1

    # Diamond squares: check each possible center and radius
    for cr in range(1, n - 1):
        for cc in range(1, m - 1):
            for r in range(1, min(cr, n - cr, cc, m - cc)):
                key = (cr, cc, r)
                valid = check_diamond_square(matrix, cr, cc, r, n, m)
                if valid:
                    seen.add(key)
                    count += 1

    return count

def check_axis_square(matrix, r1, c1, r2, c2, n, m):
    """
    Check if there's a valid axis-aligned square with top-left (r1,c1) and bottom-right (r2,c2)
    - Border cells must be '1'
    - Interior cells must be '0'
    - No '1's touching outside the border (4-way and 8-way)
    """
    s = r2 - r1 + 1
    c = c2 - c1 + 1

    # All border cells must be '1'
    for j in range(c):
        if matrix[r1][c1 + j] != '1':
            return False
        if matrix[r2][c1 + j] != '1':
            return False
    for i in range(s):
        if matrix[r1 + i][c1] != '1':
            return False
        if matrix[r1 + i][c2] != '1':
            return False

    # Interior must be '0' (only if s > 2)
    if s > 2:
        for r in range(r1 + 1, r2):
            for c_idx in range(c1 + 1, c2):
                if matrix[r][c_idx] != '0':
                    return False

    # Check no '1's touching outside the border (8-way touch check)
    # Top side
    if r1 > 0:
        for j in range(c1 - 1, c2 + 2):
            if 0 <= j < m and matrix[r1 - 1][j] != '0':
                return False
    # Bottom side
    if r2 < n - 1:
        for j in range(c1 - 1, c2 + 2):
            if 0 <= j < m and matrix[r2 + 1][j] != '0':
                return False
    # Left side
    if c1 > 0:
        for i in range(r1 - 1, r2 + 2):
            if 0 <= i < n and matrix[i][c1 - 1] != '0':
                return False
    # Right side
    if c2 < m - 1:
        for i in range(r1 - 1, r2 + 2):
            if 0 <= i < n and matrix[i][c2 + 1] != '0':
                return False

    return True

def check_diamond_square(matrix, cr, cc, r, n, m):
    """
    Check if there's a valid diamond square centered at (cr, cc) with radius r
    - Top: (cr - r, cc) must be '1'
    - Left: (cr, cc - r) must be '1'  
    - Right: (cr, cc + r) must be '1'
    - Bottom: (cr + r, cc) must be '1'
    - Center (cr, cc) must be '0'
    - No '1's touching outside the border (8-way touch check for each border cell)
    """
    # Check vertices are '1'
    if matrix[cr - r][cc] != '1' or matrix[cr][cc - r] != '1' or \
       matrix[cr][cc + r] != '1' or matrix[cr + r][cc] != '1':
        return False

    # Center must be '0'
    if matrix[cr][cc] != '0':
        return False

    # Check each border cell has no touching '1's outside (8-way)
    def check_border_cell(rv, cv):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = rv + dr, cv + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if matrix[nr][nc] == '1':
                        # Allow touching only at other diamond vertices
                        if is_diamond_neighbor(nr, nc, cr, cc, r):
                            continue
                        return False
        return True

    # Check all 4 vertices
    vertices = [(cr - r, cc), (cr, cc - r), (cr, cc + r), (cr + r, cc)]
    for rv, cv in vertices:
        if check_border_cell(rv, cv):
            continue
        else:
            return False
        # If any check fails, the diamond is invalid

    return True

def is_diamond_neighbor(r, c, cr, cc, r_rad):
    """Check if position (r,c) is another diamond vertex or the center"""
    if r == cr and c == cc:
        return True
    # Check if it's one of the 4 vertices
    if r == cr - r_rad and c == cc:
        return True
    if r == cr + r_rad and c == cc:
        return True
    if r == cr and c == cc - r_rad:
        return True
    if r == cr and c == cc + r_rad:
        return True
    return False
