```python
from collections import defaultdict, deque

def solution(input_str):
    # Handle empty input
    if not input_str or not input_str.strip():
        return '0\n'

    lines = input_str.strip().split('\n')
    if len(lines) == 0 or not lines[0].strip():
        return '0\n'

    first_parts = lines[0].split()
    if not first_parts:
        return '0\n'

    try:
        n, k = int(first_parts[0]), int(first_parts[1])
    except ValueError:
        return '0\n'

    # Edge cases: k=1 or k=n means we can use the whole graph or single node
    if k == 1 or k == n:
        return '0\n'

    # Handle n=1 separately
    if n == 1:
        return '0\n'

    # Parse edges (store 1-based index)
    adj = defaultdict(list)
    edge_list = []  # (u, v, original_index)

    for idx, line in enumerate(lines[1:]):
        if not line.strip():
            continue
        parts = line.split()
        if len(parts) >= 2:
            try:
                u, v = int(parts[0]), int(parts[1])
                adj[u].append(v)
                adj[v].append(u)
                edge_list.append((u, v, idx + 1))
            except ValueError:
                continue

    if len(edge_list) < n - 1 or n == 1:
        return '0\n'

    best_boundaries = float('inf')
    best_edges = []

    # Try starting from each possible root and find k connected nodes via BFS
    for start_node in range(1, n + 1):
        # BFS to find exactly k connected nodes containing start_node
        visited = set()
        component = []
        queue = deque([start_node])
        visited.add(start_node)
        component.append(start_node)

        while queue and len(component) < k:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
                    component.append(neighbor)

        # Skip if we couldn't get exactly k nodes (though in a tree this should always work)
        if len(component) != k:
