    in_degree = [0] * (n + 1)
    root = 0

    valid_tree = True
    for i in range(1, n + 1):
        prereq = p[i-1]
        if prereq == 0:
            root = i
        elif prereq < 1 or prereq > n:
            valid_tree = False
            break
        else:
            children[prereq].append(i)
            in_degree[i] = 1

    if not valid_tree or root == 0:
        return "0\n"

    # Check if all nodes are connected (single tree)
    visited_count = 0
    def dfs_count(u, visited):
        nonlocal visited_count
        visited[u] = True
        visited_count += 1
        for v in children[u]:
            if not visited[v]:
                dfs_count(v, visited)

    visited = [False] * (n + 1)
    dfs_count(root, visited)
    if visited_count != n:
        return "0\n"

    # Backtracking to find valid ordering with special pairs
    ans = None

    def solve(current_order, visited):
        nonlocal ans
        if ans is not None:
            return

        if len(current_order) == n:
            ans = current_order[:]
            return True

        # Try each unvisited node as next element
        for v in range(1, n + 1):
            if not visited[v]:
                # All parents of v must be in current_order
                valid = True
                for child in children[v]:
                    if not visited[child]:
                        valid = False
                        break

                if valid:
                    new_order = current_order + [v]
                    new_visited = visited[:]
                    new_visited[v] = True
                    solve(new_order, new_visited)
                    if ans is not None:
