import random


def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1\n'

    N = int(lines[0])

    # Build full N×N cost matrix
    full_costs = [[0] * N for _ in range(N)]
    for i in range(N):
        row = list(map(int, lines[i+1].split()))
        for j in range(N):
            if j != i:
                # The row contains costs to all other cities
                # For city i, get these in order (skipping i itself)
                pos = j if j < i else j - 1
                full_costs[i][j] = row[pos]

    # Build preferences (lower cost = better preference)
    preferences = []
    for i in range(N):
        prefs = []
        for j in range(N):
            if i != j:
                prefs.append((-full_costs[i][j], j))  # Negate for descending sort, but we want ascending
        prefs.sort(key=lambda x: -x[0])  # Higher score (less negated) = lower actual cost = higher preference
        preferences.append([p[1] for p in prefs])

    # Check if matching is stable
    def is_stable(match):
        for i in range(N):
            if match[i] == -1:
                continue
            # cost of current match for city i
            current_i = full_costs[i][match[i]]

            for j in range(i + 1, N):
                if match[j] == -1:
                    continue

                current_j = full_costs[j][match[j]]

                # Check if (i, j) is a blocking pair
                cost_ij = full_costs[i][j]
                cost_ji = full_costs[j][i]

                if cost_ij < current_i and cost_ji < current_j:
                    return False

        return True

    # Try multiple random matchings to find a stable one
    max_attempts = 100 * N if N <= 50 else 20000

    best_match = None

    for attempt in range(max_attempts):
        match = [-1] * N
        for k in range(0, N, 2):
            if k + 1 < N:
                u, v = random.sample(range(N), 2)
                match[u] = v
                match[v] = u
            else:
                break

        if is_stable(match):
            # Convert to output format (add 1 to each for 1-based indexing)
            result = [str(match[i] + 1) for i in range(N)]
            return '\n'.join(result) + '\n'

    return '-1\n'
