    def is_exceed(av, bv):
        if av == 1:
            return False  # 1^b = 1 < n (n >= 2)
        if bv == 0:
            return False  # av^0 = 1 < n
        # Compute av^bv with early termination to avoid overflow
        result = 1
        for _ in range(bv):
            result *= av
            if result >= n:
                return True
        return result >= n

    # Game theory function: returns True if current player can force a win
    def can_win(av, bv):
        if (av, bv) in memo:
            return memo[(av, bv)]

        # Check if moves are safe (don't immediately lose)
